        ['code' => 'BR-009', 'section' => 'Project Information and Requirements', 'title' => 'Scope Definition', 'text' => "The generated project plan must reflect the project scope identified from the user's requirements.\nThe project scope should identify:\n- Major functions to be delivered.\n- Relevant systems or platforms.\n- Major integrations.\n- Major user groups.\n- Important exclusions where they are known.", 'evaluation_type' => 'policy', 'is_mandatory' => true],
